+          }
+        ]
       }
     ],
     "UserPromptSubmit": [
@@ -37,9 +93,18 @@
           {
             "type": "command",
             "command": "p=$(cat); if printf '%s' \"$p\" | grep -Eiq '(fix|fixing|repro|reproduce|debug|broken|regression).*(bug|issue|defect|problem|error)|(bug|issue|defect|regression).*(fix|repro)'; then printf 'Reminder: this prompt looks like a bug-fix request. Invoke the bug-fix-tdd skill and follow its test-first workflow (write failing fix_case + passing bug_case BEFORE editing production code).'; fi"
+          },
+          {
+            "type": "command",
+            "command": "sh -c 'if ! command -v entire >/dev/null 2>&1; then exit 0; fi; exec entire hooks claude-code user-prompt-submit'"
           }
         ]
       }
     ]
+  },
+  "permissions": {
+    "deny": [
+      "Read(./.entire/metadata/**)"
+    ]
   }
